44	    OP_PARAM_RSV_CHECK(opParam);
45	    ATB_LOG(INFO) << "CreateOperation MultinomialParam numSamples: " << opParam.numSamples
46	                  << ", randSeed: " << opParam.randSeed;
47	    if (!(GetSingleton<Config>().Is910B())) {
48	        ATB_LOG(ERROR) << "multinomial only supports Atlas 800I A2/A3 inference product!";
