84	    outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0];
85	    outTensorDescs.at(0).shape.dims[1] = param_.numSamples;
86	    outTensorDescs.at(0).shape.dimNum = OUT_TENSOR_DIM_NUM;
