97	Status MultinomialOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
98	{
99	    Status ret = DimNumCheck(inTensors.at(0).desc);
100	    if (ret != NO_ERROR) {
101	        return ret;
102	    }
103	    uint64_t dimNum = inTensors.at(0).desc.shape.dimNum;
104	    int64_t lastDim = inTensors.at(0).desc.shape.dims[dimNum - 1];
105	    if (param_.numSamples > static_cast<uint64_t>(lastDim)) {
106	        ATB_LOG(ERROR) << GetLogPrefix() << "numSamples shoud not be bigger than last dim, numSamples: " << param_.numSamples
107	                       << ", last dim: " << lastDim;
108	        return ERROR_INVALID_PARAM;
109	    }
110	    if (outTensors.at(0).desc.shape.dimNum != OUT_TENSOR_DIM_NUM) {
111	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensors dims is invalid, dimNum should be " << OUT_TENSOR_DIM_NUM << "but got: "
112	                                         << outTensors.at(0).desc.shape.dimNum;
113	        return ERROR_INVALID_TENSOR_DIM;
114	    }
115	    if (outTensors.at(0).desc.shape.dims[1] != param_.numSamples) {
116	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensors dims is invalid, dims[1] should be param_.numSamples, but got dims[1]: "
117	                                         << outTensors.at(0).desc.shape.dims[1] << ", param_.numSamples" << param_.numSamples;
118	        return ERROR_INVALID_TENSOR_DIM;
119	    }
120	    if (outTensors.at(0).desc.shape.dims[0] != inTensors.at(0).desc.shape.dims[0]) {
121	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensors dims[0] should be equal to inTensors dims[0], but got outTensors dims[0]: "
122	                                         << outTensors.at(0).desc.shape.dims[0] << ", inTensors dims[0]" << inTensors.at(0).desc.shape.dims[0];
123	        return ERROR_INVALID_TENSOR_DIM;
124	    }
125	
126	    return NO_ERROR;
127	}
