22	static constexpr uint32_t TENSOR_2 = 2;
23	static constexpr uint32_t TENSOR_3 = 3;
24	
25	namespace {
26	bool ParamCheck(const atb::infer::FusedAddTopkDivParam opParam)
27	{
28	    if (opParam.groupNum == 0) {
29	        ATB_LOG(ERROR) << "groupNum should not be 0";
30	        return false;
31	    }
32	    if (opParam.groupTopk == 0) {
33	        ATB_LOG(ERROR) << "groupTopk should not be 0";
34	        return false;
35	    }
36	    if (opParam.groupTopk > opParam.groupNum) {
37	        ATB_LOG(ERROR) << "groupTopk should not be larger than groupNum";
38	        return false;
39	    }
40	    if (opParam.n == 0) {
41	        ATB_LOG(ERROR) << "n should not be 0";
42	        return false;
43	    }
44	    if (opParam.k == 0) {
45	        ATB_LOG(ERROR) << "k should not be 0";
46	        return false;
47	    }
48	    if (opParam.activationType != atb::infer::ACTIVATION_SIGMOID) {
49	        ATB_LOG(ERROR) << "activationType only support ACTIVATION_SIGMOID";
50	        return false;
51	    }
52	    return true;
53	}
54	} // namespace
55	
56	namespace atb {
57	OPERATION_PARAM_FUNCS(FusedAddTopkDivOperation, infer::FusedAddTopkDivParam)
58	
59	FusedAddTopkDivOperation::FusedAddTopkDivOperation(const infer::FusedAddTopkDivParam &param)
60	    : OperationBase("FusedAddTopkDivOperation"), param_(param)
61	{
62	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(
63	        param_.enableExpertMapping ? "FusedAddTopkDivOperationExpertMapping" : "FusedAddTopkDivOperation");
64	}
65	
66	FusedAddTopkDivOperation::~FusedAddTopkDivOperation() {}
67	
68	uint32_t FusedAddTopkDivOperation::GetInputNum() const
69	{
70	    if (param_.enableExpertMapping) {
71	        return IN_TENSOR_NUM_EXPERT_MAPPING;
72	    }
73	    return IN_TENSOR_NUM;
74	}
75	
76	uint32_t FusedAddTopkDivOperation::GetOutputNum() const
77	{
78	    return OUT_TENSOR_NUM;
79	}
80	
81	infer::FusedAddTopkDivParam FusedAddTopkDivOperation::GetParam() const
82	{
83	    return param_;
84	}
85	
86	void FusedAddTopkDivOperation::SetParam(const infer::FusedAddTopkDivParam &param)
87	{
88	    param_ = param;
89	    runner_ = nullptr;
90	}
91	
92	Status FusedAddTopkDivOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
93	                                                SVector<TensorDesc> &outTensorDescs) const
94	{
95	    outTensorDescs.at(0) = inTensorDescs.at(0);
96	    outTensorDescs.at(0).dtype = ACL_FLOAT;
97	    outTensorDescs.at(0).shape.dims[1] = param_.k;
98	
99	    outTensorDescs.at(1) = inTensorDescs.at(0);
100	    outTensorDescs.at(1).dtype = ACL_INT32;
101	    outTensorDescs.at(1).shape.dims[1] = param_.k;
102	
103	    return NO_ERROR;
104	}
105	
106	Status FusedAddTopkDivOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
107	{
108	    return InTensorDescsCheck(inTensorDescs);
109	}
110	
111	Status FusedAddTopkDivOperation::SetupCheckImpl(const SVector<Tensor> &inTensors,
112	                                                const SVector<Tensor> &outTensors) const
113	{
114	    SVector<TensorDesc> inTensorDescs;
115	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
116	    Status status = InTensorDescsCheck(inTensorDescs);
117	    if (status != NO_ERROR) {
118	        return status;
119	    }
120	    return OutTensorCheck(outTensors, inTensorDescs);
121	}
122	
123	std::shared_ptr<Runner> FusedAddTopkDivOperation::CreateRunner(Context &context) const
124	{
125	    ContextBase *contextBase = dynamic_cast<ContextBase *>(&context);
126	    if (!contextBase) {
127	        ATB_LOG(DEBUG) << "context cast to contextBase failed!";
128	        return nullptr;
129	    }
130	    int64_t runnerTypeIdx = RunnerTypeRegister::GetRunnerTypeIdx("FusedAddTopkDivOpsRunner");
131	    RunnerPool &pool = contextBase->GetRunnerPool(runnerTypeIdx);
132	    Runner *runner = pool.MallocRunner<FusedAddTopkDivOpsRunner, infer::FusedAddTopkDivParam>(param_);
133	    if (!runner) {
134	        ATB_LOG(DEBUG) << "MallocRunner from pool failed!";
135	        return std::make_shared<FusedAddTopkDivOpsRunner>(param_);
136	    }
137	    return std::shared_ptr<Runner>(runner, [poolPtr = &pool](Runner *runner) { poolPtr->FreeRunner(runner); });
138	}
139	
140	nlohmann::json FusedAddTopkDivOperation::GetParamJson() const
141	{
142	    return OpParamToJson(param_);
143	}
144	
145	Status FusedAddTopkDivOperation::InTensorDescsCheck(const SVector<TensorDesc> &inTensorDescs) const
146	{
147	    if (!TensorCheck::IsTensorDescDimNumValid(inTensorDescs.at(0), 2)) { // 2: x dimNum
148	        return ERROR_INVALID_TENSOR_DIM_NUM;
149	    }
150	    int64_t inTensor0Dim1 = inTensorDescs.at(0).shape.dims[1];
151	    if (inTensor0Dim1 % param_.groupNum != 0) {
152	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dim1 should be integer multiple of groupNum"
153	                       << ",inTensor0 dim1 = " << inTensor0Dim1 << ", groupNum = " << param_.groupNum;
154	        return ERROR_INVALID_TENSOR_DIM;
155	    }
156	    if (inTensor0Dim1 < param_.k) {
157	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dim1 should not smaller than k"
158	                       << ", inTensor0 dim1 = " << inTensor0Dim1 << ", k = " << param_.k;
159	        return ERROR_INVALID_TENSOR_DIM;
160	    }
161	    if (inTensor0Dim1 < param_.groupNum * param_.n) {
162	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dim1 should not smaller than groupNum * n"
163	                       << ", inTensor0 dim1 = " << inTensor0Dim1 << ", groupNum * n = " << param_.groupNum * param_.n;
164	        return ERROR_INVALID_TENSOR_DIM;
165	    }
166	    if (inTensor0Dim1 > param_.groupNum * 32) { // 32: maximum: groupNum * 32
167	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dim1 should not larger than groupNum * 32"
168	                       << ", inTensor0 dim1 = " << inTensor0Dim1
169	                       << ", groupNum * 32 = " << (param_.groupNum * 32); // 32: maximum: groupNum * 32
170	        return ERROR_INVALID_TENSOR_DIM;
171	    }
172	    if (param_.groupNum != 8 && inTensor0Dim1 > 32) { // 8: groupNum, 32: dim1 maximum
173	        ATB_LOG(ERROR) << GetLogPrefix() << "when groupNum is not 8, inTensor0 dim1 should be less than or equal to 32"
174	                       << ", inTensor0 dim1 = " << inTensor0Dim1;
175	        return ERROR_INVALID_TENSOR_DIM;
176	    }
177	    if (!TensorCheck::IsTensorDescDimNumValid(inTensorDescs.at(1), 1)) { // 1: addMum
178	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor1 dimNum and inTensor0 dimNum should be equal"
179	                       << ", inTensor1 dimNum = " << inTensorDescs.at(1).shape.dimNum
180	                       << ", inTensor0 dimNum = " << inTensorDescs.at(0).shape.dimNum;
181	        return ERROR_INVALID_TENSOR_DIM_NUM;
182	    }
183	    if (inTensorDescs.at(1).shape.dims[0] != inTensor0Dim1) {
184	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor1 dim0 and inTensor0 dim1 should be the same"
185	                       << ", inTensor1 dim0 = " << inTensorDescs.at(1).shape.dims[0]
186	                       << ", inTensor0 dim1 = " << inTensor0Dim1;
187	        return ERROR_INVALID_TENSOR_DIM;
188	    }
189	    if (param_.enableExpertMapping) {
190	        return InTensorDescsCheckMapping(inTensorDescs);
191	    }
192	    return NO_ERROR;
193	}
194	Status FusedAddTopkDivOperation::InTensorDescsCheckMapping(const SVector<TensorDesc> &inTensorDescs) const
195	{
196	    if (!TensorCheck::IsTensorDescDimNumValid(inTensorDescs.at(TENSOR_2), 1)) {
197	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor2 dimNum should be 1"
198	                       << ", inTensor2 dimNum = " << inTensorDescs.at(TENSOR_2).shape.dimNum;
199	        return ERROR_INVALID_TENSOR_DIM_NUM;
200	    }
201	    int64_t inTensor0Dim1 = inTensorDescs.at(0).shape.dims[1];
202	    if (inTensorDescs.at(TENSOR_2).shape.dims[0] != inTensor0Dim1) {
203	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor2 dim0 and inTensor0 dim1 should be the same"
204	                       << ", inTensor2 dim0 = " << inTensorDescs.at(TENSOR_2).shape.dims[0]
205	                       << ", inTensor0 dim1 = " << inTensor0Dim1;
206	        return ERROR_INVALID_TENSOR_DIM;
207	    }
208	    if (!TensorCheck::IsTensorDescDimNumValid(inTensorDescs.at(TENSOR_3), 2)) { // 2: mappingTable dimNum
209	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor3 dimNum should be 2"
210	                       << ", inTensor3 dimNum = " << inTensorDescs.at(TENSOR_3).shape.dimNum;
211	        return ERROR_INVALID_TENSOR_DIM_NUM;
212	    }
213	    if (inTensorDescs.at(TENSOR_3).shape.dims[0] != inTensor0Dim1) {
214	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor3 dim0 and inTensor0 dim1 should be the same"
215	                       << ", inTensor3 dim0 = " << inTensorDescs.at(TENSOR_3).shape.dims[0]
216	                       << ", inTensor0 dim1 = " << inTensor0Dim1;
217	        return ERROR_INVALID_TENSOR_DIM;
218	    }
219	    if (inTensorDescs.at(TENSOR_3).shape.dims[1] > 128) { // 128 : MAX support 128
220	        ATB_LOG(ERROR) << GetLogPrefix()
221	                       << "inTensor3 dim1 and inTensor0 dim1 should be less than or equal to MAX supprt 128"
222	                       << ", inTensor3 dim1 = " << inTensorDescs.at(TENSOR_3).shape.dims[1];
223	        return ERROR_INVALID_TENSOR_DIM;
224	    }
225	    return NO_ERROR;
226	}
