228	Status FusedAddTopkDivOperation::OutTensorCheck(const SVector<Tensor> &outTensors,
229	                                                const SVector<TensorDesc> &inTensorDescs) const
230	{
231	    const TensorDesc &yTensorDesc = outTensors.at(0).desc;
232	    const TensorDesc &indicesTensorDesc = outTensors.at(1).desc;
233	    if (!TensorCheck::IsTensorDescDimNumValid(yTensorDesc, 2)) { // 2: x, addNum
234	        return ERROR_INVALID_TENSOR_DIM_NUM;
235	    }
236	    int64_t a = inTensorDescs.at(0).shape.dims[0];
237	    if (yTensorDesc.shape.dims[0] != a) {
238	        ATB_LOG(ERROR) << "outTensor0 dim0 and inTensor0 dim0 should be equal";
239	        return ERROR_INVALID_TENSOR_DIM;
240	    }
241	    if (yTensorDesc.shape.dims[1] != param_.k) {
242	        ATB_LOG(ERROR) << "outTensor0 dim1 should be k";
