246	    Status status = TensorCheck::TensorDescsEqual(yTensorDesc, indicesTensorDesc);
247	    if (status == ERROR_INVALID_TENSOR_DIM_NUM) {
248	        ATB_LOG(ERROR) << "outTensor0 dimNum and outTensor1 dimNum should be equal";
249	        return ERROR_INVALID_TENSOR_DIM_NUM;
