206	        expertNum = 1;
207	    } else if (!param_.deviceExpert.empty()) {
208	        expertNum = static_cast<int32_t>(param_.deviceExpert.size());
209	    }
210	    if (cumSumTensorDesc.shape.dims[0] != expertNum) {
211	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor1 dim0 [" << cumSumTensorDesc.shape.dims[0] << "] should be "
212	                       << expertNum;
213	        return ERROR_INVALID_TENSOR_DIM;
214	    }
215	
216	    if (!TensorCheck::IsTensorDescDimNumValid(originalIndexTensorDesc, 1)) {
217	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor2 dimNum should be 1 but get "
218	                       << originalIndexTensorDesc.shape.dimNum;
219	        return ERROR_INVALID_TENSOR_SIZE;
220	    }
221	    if (originalIndexTensorDesc.shape.dims[0] != topkDim0) {
222	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor2 dim0 [" << originalIndexTensorDesc.shape.dims[0]
223	                       << "] and inTensor0 dim0 [" << topkDim0 << "] should be equal";
224	        return ERROR_INVALID_TENSOR_DIM;
225	    }
226	
227	    if (!param_.deviceExpert.empty()) {
228	        TensorDesc validIndexTensorDesc = outTensors.at(outTensorId++).desc;
229	        if (!TensorCheck::IsTensorDescDimNumValid(validIndexTensorDesc, 1)) {
230	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor3 dimNum should be 1 but get "
231	                           << validIndexTensorDesc.shape.dimNum;
232	            return ERROR_INVALID_TENSOR_SIZE;
233	        }
234	        if (validIndexTensorDesc.shape.dims[0] != 1) {
235	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor3 dim0 [" << validIndexTensorDesc.shape.dims[0]
236	                           << "] should be 1";
237	            return ERROR_INVALID_TENSOR_DIM;
238	        }
239	    }
240	
241	    return NO_ERROR;
242	}
243	} // namespace atb

