105	Status GroupedMatmulWithRoutingOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
106	                                                         SVector<TensorDesc> &outTensorDescs) const
107	{
108	    if (param_.groupedMatmulType == infer::GroupedMatmulWithRoutingParam::GroupedMatmulType::GROUPED_MATMUL_UP) {
109	        outTensorDescs.at(0) = inTensorDescs.at(0);
110	        outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0] * param_.topK;
111	    } else {
112	        outTensorDescs.at(0) = inTensorDescs.at(0);
113	        outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0] / param_.topK;
114	    }
115	    outTensorDescs.at(0).shape.dims[1] = OperationUtil::GetYTensorN(inTensorDescs.at(1), param_.transposeB);
116	    if (param_.outDataType != ACL_DT_UNDEFINED) {
117	        outTensorDescs.at(0).dtype = param_.outDataType;
118	    }
119	    return NO_ERROR;
120	}
121	
122	Status GroupedMatmulWithRoutingOperation::OutTensorDimCheck(const SVector<TensorDesc> &inTensorDescs,
123	                                                            const SVector<Tensor> &outTensors) const
124	{
125	    TensorDesc resultTensor = outTensors.at(0).desc;
126	    if (param_.groupedMatmulType == infer::GroupedMatmulWithRoutingParam::GroupedMatmulType::GROUPED_MATMUL_UP) {
127	        if (resultTensor.shape.dims[0] != inTensorDescs.at(0).shape.dims[0] * param_.topK) {
128	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 first dim error";
129	            return ERROR_INVALID_TENSOR_DIM;
130	        }
131	    } else {
132	        if (resultTensor.shape.dims[0] * param_.topK != inTensorDescs.at(0).shape.dims[0]) {
133	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 first dim error";
134	            return ERROR_INVALID_TENSOR_DIM;
135	        }
136	    }
137	    uint32_t outHiddenSize = inTensorDescs.at(1).shape.dims[WEIGHT_FIRST_DIM];
138	    if (!param_.transposeB) {
139	        outHiddenSize = inTensorDescs.at(1).shape.dims[WEIGHT_SECOND_DIM];
140	    }
141	    if (resultTensor.shape.dims[1] != outHiddenSize) {
142	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 second dim should be equal to hidden_size_out";
143	        return ERROR_INVALID_TENSOR_DIM;
144	    }
145	    return NO_ERROR;
146	}
