148	bool GroupedMatmulWithRoutingOperation::TokenExpertTensorCheck(const TensorDesc &acTensorDesc,
149	                                                               const TensorDesc &expertWeightDesc) const
150	{
151	    uint32_t acTensorHiddenSize = acTensorDesc.shape.dims[1];
152	    uint32_t expertWeightHiddenInSize = expertWeightDesc.shape.dims[WEIGHT_SECOND_DIM];
153	    uint32_t expertWeightHiddenOutSize = expertWeightDesc.shape.dims[WEIGHT_FIRST_DIM];
154	    if (!param_.transposeB) {
155	        expertWeightHiddenInSize = expertWeightDesc.shape.dims[WEIGHT_FIRST_DIM];
156	        expertWeightHiddenOutSize = expertWeightDesc.shape.dims[WEIGHT_SECOND_DIM];
157	    }
158	    if (acTensorHiddenSize != expertWeightHiddenInSize) {
159	        ATB_LOG(ERROR) << GetLogPrefix() << "the second dim of intensor0 is not match the hidden size of intensor1";
160	        return false;
161	    }
162	    if (expertWeightHiddenInSize % ALIGHMENT_NUMBER != 0 || expertWeightHiddenOutSize % ALIGHMENT_NUMBER != 0) {
163	        ATB_LOG(ERROR) << GetLogPrefix() << "The hidden size of intensor1 is not 32-bit aligned";
164	        return false;
165	    }
166	    if (param_.groupedMatmulType == infer::GroupedMatmulWithRoutingParam::GroupedMatmulType::GROUPED_MATMUL_UP) {
167	        if (acTensorHiddenSize < UP_HIDDEN_IN_MIN_VALUE || acTensorHiddenSize > UP_HIDDEN_IN_MAX_VALUE) {
168	            ATB_LOG(ERROR) << GetLogPrefix() << "The dimension of hidden size in exceeds the range from 32 to 5120";
169	            return false;
170	        }
171	        if (expertWeightHiddenOutSize < UP_HIDDEN_OUT_MIN_VALUE ||
172	            expertWeightHiddenOutSize > UP_HIDDEN_OUT_MAX_VALUE) {
173	            ATB_LOG(ERROR) << GetLogPrefix() << "The dimension of hidden size out exceeds the range from 32 to 256";
174	            return false;
175	        }
176	    } else {
177	        if (acTensorHiddenSize < DOWN_HIDDEN_IN_MIN_VALUE || acTensorHiddenSize > DOWN_HIDDEN_IN_MAX_VALUE) {
178	            ATB_LOG(ERROR) << GetLogPrefix() << "The dimension of hidden size in exceeds the range from 32 to 256";
179	            return false;
180	        }
181	        if (expertWeightHiddenOutSize < DOWN_HIDDEN_OUT_MIN_VALUE ||
182	            expertWeightHiddenOutSize > DOWN_HIDDEN_OUT_MAX_VALUE) {
183	            ATB_LOG(ERROR) << GetLogPrefix() << "The dimension of hidden size out exceeds the range from 32 to 5120";
184	            return false;
185	        }
186	    }
187	    return true;
188	}
