190	bool GroupedMatmulWithRoutingOperation::ExpertCountTensorCheck(const TensorDesc &expertCount,
191	                                                               const TensorDesc &expertWeightDesc) const
192	{
193	    uint32_t nExperts = expertCount.shape.dims[0];
194	    if (nExperts != expertWeightDesc.shape.dims[0]) {
195	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor1 first dim not equal to inTensor2";
196	        return false;
197	    }
198	    if (nExperts < WEIGHT_MIN_VALUE || nExperts > WEIGHT_MAX_VALUE) {
199	        ATB_LOG(ERROR) << GetLogPrefix() << "The number of expert exceeds the range from 128 to 256";
200	        return false;
201	    }
202	    return true;
203	}
204	
205	bool GroupedMatmulWithRoutingOperation::ExpertIndexTensorCheck(const TensorDesc &acTensorDesc,
206	                                                               const TensorDesc &expertIndex) const
207	{
208	    uint32_t nTokens = acTensorDesc.shape.dims[0];
209	    if (param_.groupedMatmulType == infer::GroupedMatmulWithRoutingParam::GroupedMatmulType::GROUPED_MATMUL_UP) {
210	        if (nTokens * param_.topK != expertIndex.shape.dims[0]) {
211	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor3 first dim not equal to inTensor0 multiply topK";
212	            return false;
213	        }
214	    } else {
215	        nTokens /= param_.topK;
216	        if (acTensorDesc.shape.dims[0] != expertIndex.shape.dims[0]) {
217	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor3 first dim not equal to inTensor0";
218	            return false;
219	        }
220	    }
221	    if (nTokens < ACTIVATION_MIN_VALUE || nTokens > ACTIVATION_MAX_VALUE) {
222	        ATB_LOG(ERROR) << GetLogPrefix() << "The number of activation token exceeds the range from 128 to 512";
223	        return false;
224	    }
225	    return true;
226	}
227	
228	bool GroupedMatmulWithRoutingOperation::NScaleTensorCheck(const TensorDesc &nScaleDesc,
229	                                                          const TensorDesc &expertWeightDesc) const
230	{
231	    if (nScaleDesc.shape.dims[0] != expertWeightDesc.shape.dims[0]) {
232	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor4 first dim not equal to inTensor1";
233	        return false;
234	    }
235	    uint32_t expertWeightHiddenSize = expertWeightDesc.shape.dims[WEIGHT_FIRST_DIM];
236	    if (!param_.transposeB) {
237	        expertWeightHiddenSize = expertWeightDesc.shape.dims[WEIGHT_SECOND_DIM];
238	    }
239	    if (nScaleDesc.shape.dims[1] != expertWeightHiddenSize) {
240	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor4 second dim not equal to hidden size of inTensor1";
241	        return false;
242	    }
243	    return true;
244	}
245	
246	bool GroupedMatmulWithRoutingOperation::MScaleTensorCheck(const TensorDesc &mScaleDesc,
247	                                                          const TensorDesc &acTensorDesc) const
248	{
249	    if (mScaleDesc.shape.dims[0] != acTensorDesc.shape.dims[0]) {
250	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor5 first dim not equal to inTensor0";
251	        return false;
252	    }
253	    return true;
254	}
255	
256	Status GroupedMatmulWithRoutingOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
257	{
258	    TensorDesc acTensorDesc = inTensorDescs.at(IN_TENSOR_ACTENSOR);
259	    TensorDesc expertWeightDesc = inTensorDescs.at(IN_TENSOR_EXPERTWEIGHT);
260	    if (!TokenExpertTensorCheck(acTensorDesc, expertWeightDesc)) {
261	        return ERROR_INVALID_TENSOR_DIM;
262	    }
263	    if (!ExpertCountTensorCheck(inTensorDescs.at(IN_TENSOR_EXPERTCOUNT), expertWeightDesc)) {
264	        return ERROR_INVALID_TENSOR_DIM;
265	    }
266	    if (!ExpertIndexTensorCheck(acTensorDesc, inTensorDescs.at(IN_TENSOR_EXPERTINDEX))) {
267	        return ERROR_INVALID_TENSOR_DIM;
268	    }
269	    if (param_.outDataType == ACL_DT_UNDEFINED) {
270	        return NO_ERROR;
271	    }
272	    if (!NScaleTensorCheck(inTensorDescs.at(IN_TENSOR_NSCALE), expertWeightDesc)) {
273	        return ERROR_INVALID_TENSOR_DIM;
274	    }
275	    if (!MScaleTensorCheck(inTensorDescs.at(IN_TENSOR_MSCALE), acTensorDesc)) {
276	        return ERROR_INVALID_TENSOR_DIM;
277	    }
278	    return NO_ERROR;
279	}
