281	Status GroupedMatmulWithRoutingOperation::SetupCheckImpl(const SVector<Tensor> &inTensors,
282	                                                         const SVector<Tensor> &outTensors) const
283	{
284	    SVector<TensorDesc> inTensorDescs;
