29	template <> Status CreateOperation(const infer::GroupTopkParam &opParam, Operation **operation)
30	{
31	    if (operation == nullptr) {
32	        return ERROR_INVALID_PARAM;
33	    }
34	    OP_PARAM_RSV_CHECK(opParam);
35	    ATB_LOG(INFO) << "CreateOperation GroupTopkParam groupNum: " << opParam.groupNum << ", k: " << opParam.k
36	                  << ", groupMultiFlag:" << opParam.groupMultiFlag << ", n:" << opParam.n;
37	    if (opParam.groupNum < 1) {
38	        ATB_LOG(ERROR) << "param groupNum should >= 1";
39	        return ERROR_INVALID_PARAM;
40	    }
41	    if (opParam.k < 1) {
42	        ATB_LOG(ERROR) << "param k should >= 1";
43	        return ERROR_INVALID_PARAM;
44	    }
45	    if (opParam.k > opParam.groupNum) {
46	        ATB_LOG(ERROR) << "param groupNum and param k should satisfy the relationship: k <= groupNum";
47	        return ERROR_INVALID_PARAM;
48	    }
49	    if (opParam.groupMultiFlag > infer::GroupTopkParam::GroupMultiFlag::SUM_MULTI_MAX) {
50	        ATB_LOG(ERROR) << "param groupMultiFlag is invalid";
51	        return ERROR_INVALID_PARAM;
52	    }
53	    if (opParam.groupMultiFlag == infer::GroupTopkParam::GroupMultiFlag::SUM_MULTI_MAX && opParam.n == 0) {
54	        ATB_LOG(ERROR) << "param n should >= 1 when groupMultiFlag is SUM_MULTI_MAX";
55	        return ERROR_INVALID_PARAM;
56	    }
57	    if (!GetSingleton<Config>().Is910B()) {
58	        ATB_LOG(ERROR) << "groupTopk op only support Atlas 800I A2 inference product";
59	        return ERROR_INVALID_PARAM;
60	    }
61	    *operation = new (std::nothrow) GroupTopkOperation(opParam);
62	    if (*operation == nullptr) {
63	        ATB_LOG(ERROR) << "failed to new operation";
64	        return ERROR_OUT_OF_HOST_MEMORY;
65	    }
66	    return NO_ERROR;
67	}
