99	Status GroupTopkOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
100	{
101	    SVector<TensorDesc> inTensorDescs;
102	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
103	    Status status = InTensorDescsCheck(inTensorDescs);
104	    if (status != NO_ERROR) {
105	        return status;
106	    }
107	
108	    TensorDesc varTensorDesc = inTensors.at(0).desc;
109	    TensorDesc outTensorDesc = outTensors.at(0).desc;
110	    status = TensorCheck::TensorDescsEqual(varTensorDesc, outTensorDesc);
111	    if (status == ERROR_INVALID_TENSOR_DIM_NUM) {
112	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 dimNum [" << outTensorDesc.shape.dimNum
113	                       << "] and inTensor0 dimNum [" << varTensorDesc.shape.dimNum << "] should be equal";
114	        return status;
115	    }
116	    if (status == ERROR_INVALID_TENSOR_DIM) {
117	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 dims and inTensor0 dims should be the same";
118	        return status;
119	    }
120	    return OutTensorsCheck(outTensors);
