134	Status GroupTopkOperation::InTensorDescsCheck(const SVector<TensorDesc> &inTensorDescs) const
135	{
136	    size_t inTensorDescId = 0;
137	    TensorDesc tokenTensorDesc = inTensorDescs.at(inTensorDescId++);
138	    TensorDesc idxArrTensorDesc = inTensorDescs.at(inTensorDescId++);
139	
140	    if (!TensorCheck::IsTensorDescDimNumValid(tokenTensorDesc, DIM_NUM_2)) {
141	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dimNum should be " << DIM_NUM_2 << " but get "
142	                       << tokenTensorDesc.shape.dimNum;
143	        return ERROR_INVALID_TENSOR_DIM_NUM;
144	    }
145	
146	    if (!TensorCheck::IsTensorDescDimNumValid(idxArrTensorDesc, 1)) {
147	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor1 dimNum should be 1 but get " << idxArrTensorDesc.shape.dimNum;
148	        return ERROR_INVALID_TENSOR_DIM_NUM;
149	    }
150	
151	    int64_t expertNum = tokenTensorDesc.shape.dims[1];
152	
153	    // param_.groupNum取值范围判断 [1, expertNum]
154	    if (param_.groupNum < 1 || param_.groupNum > expertNum) {
155	        ATB_LOG(ERROR) << GetLogPrefix() << "groupNum should in scope [1, " << expertNum << "], but get "
156	                       << param_.groupNum;
157	        return ERROR_INVALID_PARAM;
158	    }
159	
160	    // param_.k取值范围判断 [1, groupNum]
161	    if (param_.k < 1 || param_.k > param_.groupNum) {
162	        ATB_LOG(ERROR) << GetLogPrefix() << "k should in scope [1, " << param_.groupNum << "], but get " << param_.k;
163	        return ERROR_INVALID_PARAM;
164	    }
165	
166	    // param_.n取值范围判断 [1, expertNum / groupNum], 1在创建时已校验
167	    if (param_.groupMultiFlag == infer::GroupTopkParam::GroupMultiFlag::SUM_MULTI_MAX &&
168	        param_.n > expertNum / param_.groupNum) {
169	        ATB_LOG(ERROR) << GetLogPrefix() << "n should <= " << expertNum / param_.groupNum << ", but get " << param_.n;
170	        return ERROR_INVALID_PARAM;
171	    }
172	
173	    // expertNum能被groupNum整除判断
174	    if (expertNum % param_.groupNum != 0) {
175	        ATB_LOG(ERROR) << GetLogPrefix() << "expert num " << expertNum
176	                       << " should be divided with no remainder by groupNum " << param_.groupNum;
177	        return ERROR_INVALID_PARAM;
178	    }
179	
180	    // inTensor1.shape.dims[0] == 1024 判断
181	    if (idxArrTensorDesc.shape.dims[0] != IN_TENSOR_SHAPE_0) {
182	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor1 dim[0] should be " << IN_TENSOR_SHAPE_0 << ", but get "
183	                       << idxArrTensorDesc.shape.dims[0];
184	        return ERROR_INVALID_TENSOR_DIM;
185	    }
186	
187	    // inTensor0.shape.dims[1]取值范围为 [1,1024]
188	    if (tokenTensorDesc.shape.dims[1] < 1 || tokenTensorDesc.shape.dims[1] > MAX_EXPERT) {
189	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor0 dim[1] should in scope [1, " << MAX_EXPERT << "], but get "
190	                       << tokenTensorDesc.shape.dims[1];
191	        return ERROR_INVALID_TENSOR_DIM;
192	    }
193	
194	    return NO_ERROR;
195	}
